const MC = [{"id": "m1", "title": "Celsius to kelvin", "topic": "Temperature", "q": "A temperature of 58 °C is equal to:", "options": ["−215 K", "215 K", "−331 K", "331 K"], "answer": 3, "hint": "Convert Celsius to kelvin by adding 273.", "steps": [{"text": "Write the Celsius-to-kelvin conversion.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>T</mi><mrow><mtext>K</mtext></mrow></msub><mo>=</mo><msub><mi>θ</mi><mrow><mtext>°C</mtext></mrow></msub><mo>+</mo><mn>273</mn></mrow></math>"]}, {"text": "Put in the Celsius temperature.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>T</mi><mrow><mtext>K</mtext></mrow></msub><mo>=</mo><mn>58</mn><mo>+</mo><mn>273</mn></mrow></math>"]}, {"text": "Add the numbers.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mn>331</mn><mspace width=\"0.2em\"/><mtext>K</mtext></mrow></math>"]}], "trap": "Kelvin uses K, without a degree symbol. The exact conversion adds 273.15; 331 K is the matching option.", "image": "assets/q1.png", "graph": null, "note": null, "formulas": [{"name": "Celsius to kelvin", "equation": "T / K = θ / °C + 273", "symbols": "T with subscript K is the temperature in kelvin; θ is the Celsius temperature. Use 273 for this question; the exact offset is 273.15.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>T</mi><mrow><mtext>K</mtext></mrow></msub><mo>=</mo><msub><mi>θ</mi><mrow><mtext>°C</mtext></mrow></msub><mo>+</mo><mn>273</mn></mrow></math>"]}]}, {"id": "m2", "title": "Power from a star", "topic": "Radiation", "q": "The total power radiated by a star is called its", "options": ["Apparent brightness", "Albedo", "Stellar constant", "Luminosity"], "answer": 3, "hint": "Think of all the energy leaving the star every second.", "steps": [{"text": "Luminosity means the total energy emitted each second: it is the star’s total power.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>t</mi></mrow></mfrac></mrow></math>"]}, {"text": "Its unit is the watt. Apparent brightness describes the power received per square metre at the observer, so the answer is D: luminosity.", "math": []}], "trap": "Distance changes apparent brightness, but does not change the star’s luminosity.", "image": "assets/q2.png", "graph": null, "note": null, "formulas": [{"name": "Power / luminosity", "equation": "L = Q/t", "symbols": "L = total emitted power or luminosity (W); Q = total energy emitted (J); t = time (s).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>t</mi></mrow></mfrac></mrow></math>"]}]}, {"id": "m3", "title": "Melting ice", "topic": "Phase changes", "q": "A thermally isolated container has 10 kg of ice. The specific latent heat of fusion of ice is 0.336 MJ kg⁻¹. How much energy must be supplied to the ice to completely melt it, without changing its temperature?", "options": ["0.0336 MJ", "0.336 MJ", "3.36 MJ", "33.6 MJ"], "answer": 2, "hint": "For melting at constant temperature, use Q = mL.", "steps": [{"text": "Melting changes the state without changing temperature, so use latent heat.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>"]}, {"text": "The unknown Q is already on its own; no rearrangement is needed.", "math": []}, {"text": "Substitute the mass and the latent heat in MJ per kg.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mn>10</mn><mo>×</mo><mn>0.336</mn></mrow></math>"]}, {"text": "Multiply. The kg units cancel, leaving MJ.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mn>3.36</mn><mspace width=\"0.2em\"/><mtext>MJ</mtext></mrow></math>"]}], "trap": "Use latent heat for a change of state; use Q = mcΔT for a temperature change.", "image": "assets/q3.png", "graph": null, "note": null, "formulas": [{"name": "Change of state", "equation": "Q = mL", "symbols": "Q = energy transferred (J); m = mass (kg); L = specific latent heat (J kg⁻¹). Temperature stays constant during the change of state.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>"]}]}, {"id": "m4", "title": "Energy transfer mechanisms", "topic": "Energy transfer", "q": "Which of the following is not a primary mechanism for thermal energy transfer?", "options": ["Friction", "Conduction", "Thermal radiation", "Convection"], "answer": 0, "hint": "Recall the three main thermal transfer mechanisms.", "steps": ["The three mechanisms are conduction, convection and radiation.", "Friction converts mechanical energy into internal energy.", "So friction is the answer."], "trap": "Friction can heat an object, but is not one of the three thermal transfer mechanisms.", "image": "assets/q4.png", "graph": null, "note": null}, {"id": "m5", "title": "Freezing and internal energy", "topic": "Phase changes", "q": "A substance turns from a liquid into a solid. The temperature of the substance does not change during the process. Which of the following statements is true about the process?", "options": ["Energy is supplied to the substance.", "The total internal energy of the system decreases.", "The kinetic energy of the molecules in the substance decreases.", "The intermolecular potential energy of the substance is unchanged."], "answer": 1, "hint": "Internal energy includes particle kinetic energy and potential energy.", "steps": ["Constant temperature means the average particle kinetic energy stays the same.", "During freezing, intermolecular potential energy decreases.", "Energy leaves the substance, so its internal energy decreases."], "trap": "A constant temperature does not mean constant internal energy.", "image": "assets/q5.png", "graph": null, "note": null}, {"id": "m6", "title": "Density of a smaller cube", "topic": "Density", "q": "The density of a metal cube with side length L and mass M is ρ.\n\nWhat is the density of a metal cube with side length L/2 and mass M/4?", "options": ["ρ/4", "4ρ", "ρ/2", "2ρ"], "answer": 3, "hint": "The volume of a cube is the side length cubed.", "steps": [{"text": "Write the original density and cube volume.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>ρ</mi><mo>=</mo><mfrac><mrow><mi>M</mi></mrow><mrow><mi>V</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>V</mi><mo>=</mo><msup><mi>L</mi><mn>3</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>ρ</mi><mo>=</mo><mfrac><mrow><mi>M</mi></mrow><mrow><msup><mi>L</mi><mn>3</mn></msup></mrow></mfrac></mrow></math>"]}, {"text": "Cube the new side length. Cube the top and bottom of the fraction.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>V</mi><mrow><mtext>new</mtext></mrow></msub><mo>=</mo><mo>(</mo><mfrac><mrow><mi>L</mi></mrow><mrow><mn>2</mn></mrow></mfrac><msup><mo>)</mo><mn>3</mn></msup><mo>=</mo><mfrac><mrow><msup><mi>L</mi><mn>3</mn></msup></mrow><mrow><msup><mn>2</mn><mn>3</mn></msup></mrow></mfrac><mo>=</mo><mfrac><mrow><msup><mi>L</mi><mn>3</mn></msup></mrow><mrow><mn>8</mn></mrow></mfrac></mrow></math>"]}, {"text": "Insert the new mass and new volume into density = mass ÷ volume.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>ρ</mi><mrow><mtext>new</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mfrac><mrow><mi>M</mi></mrow><mrow><mn>4</mn></mrow></mfrac></mrow><mrow><mfrac><mrow><msup><mi>L</mi><mn>3</mn></msup></mrow><mrow><mn>8</mn></mrow></mfrac></mrow></mfrac></mrow></math>"]}, {"text": "Dividing by a fraction means multiplying by its reciprocal: turn the second fraction upside down.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>ρ</mi><mrow><mtext>new</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mi>M</mi></mrow><mrow><mn>4</mn></mrow></mfrac><mo>×</mo><mfrac><mrow><mn>8</mn></mrow><mrow><msup><mi>L</mi><mn>3</mn></msup></mrow></mfrac></mrow></math>"]}, {"text": "Collect the numerical factors and simplify.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>ρ</mi><mrow><mtext>new</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mn>8</mn></mrow><mrow><mn>4</mn></mrow></mfrac><mo>×</mo><mfrac><mrow><mi>M</mi></mrow><mrow><msup><mi>L</mi><mn>3</mn></msup></mrow></mfrac><mo>=</mo><mn>2</mn><mfrac><mrow><mi>M</mi></mrow><mrow><msup><mi>L</mi><mn>3</mn></msup></mrow></mfrac></mrow></math>"]}, {"text": "The original density is M divided by L cubed, so replace that fraction with ρ.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>ρ</mi><mrow><mtext>new</mtext></mrow></msub><mo>=</mo><mn>2</mn><mi>ρ</mi></mrow></math>"]}], "trap": "Halving every side reduces volume to one eighth, not one half.", "image": "assets/q6.png", "graph": null, "note": null, "formulas": [{"name": "Density", "equation": "ρ = m/V  →  m = ρV", "symbols": "ρ = density (kg m⁻³); m = mass (kg); V = volume (m³).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>ρ</mi><mo>=</mo><mfrac><mrow><mi>m</mi></mrow><mrow><mi>V</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>ρ</mi><mi>V</mi><mo>=</mo><mfrac><mrow><mi>m</mi></mrow><mrow><mi>V</mi></mrow></mfrac><mi>V</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mi>ρ</mi><mi>V</mi></mrow></math>"]}, {"name": "Cube volume", "equation": "V = s³", "symbols": "s = side length of the cube (m). For this question the original side is L, so V = L³.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>V</mi><mo>=</mo><msup><mi>s</mi><mn>3</mn></msup></mrow></math>"]}]}, {"id": "m7", "title": "Water changing phase", "topic": "Phase changes", "q": "A thermally isolated tube contains only water molecules. The tube is cooled to the freezing point of water. While the water is changing phase:", "options": ["its temperature decreases.", "the mean potential energy of the water molecules decreases.", "the mean kinetic energy of the water molecules decreases.", "the mean thermal energy of the water molecules decreases."], "answer": 1, "hint": "At a phase change, temperature stays constant.", "steps": ["Water freezing at constant temperature keeps the same average kinetic energy.", "The molecules settle into a lower potential energy arrangement.", "The intended answer is B: mean potential energy decreases."], "trap": "The supplied wording calls the tube thermally isolated and also says it is cooled. An external cooling process requires energy transfer. Option D uses “thermal energy” imprecisely; B is the intended precise molecular statement.", "image": "assets/q7.png", "graph": null, "note": null}, {"id": "m8", "title": "A spacecraft without an atmosphere", "topic": "Energy transfer", "q": "A spacecraft is at rest on the surface of a planet. The planet has no atmosphere. The spacecraft is losing energy mainly through:", "options": ["Conduction, convection and radiation", "Convection and radiation", "Conduction and convection", "Conduction and radiation"], "answer": 3, "hint": "Which mechanism needs a moving liquid or gas?", "steps": ["Contact with the ground allows conduction.", "The spacecraft emits thermal radiation.", "No atmosphere means no atmospheric convection.", "Choose conduction and radiation."], "trap": "A vacuum prevents convection through air, but does not prevent radiation.", "image": "assets/q8.png", "graph": null, "note": null}, {"id": "m9", "title": "Mass of heated water", "topic": "Heating", "q": "Water is heated from 40 °C to 50 °C in a thermally isolated container. The total energy supplied to the water is 84000 J. The specific heat capacity of water is 4200 J kg⁻¹ K⁻¹. What is the mass of the water?", "options": ["0.2 kg", "0.5 kg", "2.0 kg", "5.0 kg"], "answer": 2, "hint": "Start with Q = mcΔT and find the temperature change.", "steps": [{"text": "Find the temperature change.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Δ</mi><mi>T</mi><mo>=</mo><mn>50</mn><mo>−</mo><mn>40</mn><mo>=</mo><mn>10</mn><mspace width=\"0.2em\"/><mtext>K</mtext></mrow></math>"]}, {"text": "Start with the heating equation.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"text": "To leave m on its own, divide BOTH sides by cΔT.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "The cΔT factor on the right cancels. Swap the two sides to put m first.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "Substitute the values.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mfrac><mrow><mn>84000</mn></mrow><mrow><mn>4200</mn><mo>×</mo><mn>10</mn></mrow></mfrac></mrow></math>"]}, {"text": "Calculate the bottom first, then divide.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mfrac><mrow><mn>84000</mn></mrow><mrow><mn>42000</mn></mrow></mfrac><mo>=</mo><mn>2.0</mn><mspace width=\"0.2em\"/><mtext>kg</mtext></mrow></math>"]}], "trap": "A change of 10 °C equals a change of 10 K. Do not add 273 to a temperature change.", "image": "assets/q9.png", "graph": null, "note": null, "formulas": [{"name": "Temperature change", "equation": "Q = mcΔT", "symbols": "Q = energy transferred (J); m = mass (kg); c = specific heat capacity (J kg⁻¹ K⁻¹); ΔT = temperature change (K).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"name": "Rearrange for mass", "equation": "m = Q/(cΔT)", "symbols": "First find ΔT = final temperature − initial temperature. A temperature change in °C has the same numerical value in K.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>"]}]}, {"id": "m10", "title": "Temperature while melting", "topic": "Phase changes", "q": "Energy is supplied to a solid that is initially at its melting point. This process continues until the solid is completely melted. Which of the following graphs correctly shows how the temperature of the solid varies with the energy supplied to the solid?", "options": ["Graph A", "Graph B", "Graph C", "Graph D"], "answer": 3, "hint": "Does temperature change during melting?", "steps": ["The energy is used to increase intermolecular potential energy.", "The average kinetic energy stays constant.", "Temperature remains constant, so the graph is horizontal: D."], "trap": "The question stops when melting finishes; it does not include warming the liquid.", "image": "assets/q10.png", "graph": "assets/q10-graph.png", "note": null, "graphWidth": 465, "graphHeight": 440}, {"id": "m11", "title": "Wien’s law relationship", "topic": "Radiation", "q": "The peak wavelength emitted by a black body at temperature T is λ.\n\nWhat is true about the relationship between T and λ?", "options": ["λ ∝ T", "λ ∝ T⁻¹", "λ ∝ T²", "λ ∝ T⁻²"], "answer": 1, "hint": "Wien’s law says λT is constant.", "steps": [{"text": "Wien’s law says the peak wavelength multiplied by temperature is constant.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>λ</mi><mi>T</mi><mo>=</mo><mi>b</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>b</mi><mo>=</mo><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mspace width=\"0.2em\"/><mtext>m K</mtext></mrow></math>"]}, {"text": "Divide BOTH sides by T to leave wavelength on its own.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>λ</mi><mi>T</mi></mrow><mrow><mi>T</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>b</mi></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "Cancel T on the left.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>λ</mi><mo>=</mo><mfrac><mrow><mi>b</mi></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "The constant b does not change. The temperature is on the bottom of the fraction: a bigger T gives a smaller wavelength.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>λ</mi><mo>∝</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "A power of −1 means “one divided by”. These are two ways of writing the same relationship.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msup><mi>T</mi><mrow><mo>−</mo><mn>1</mn></mrow></msup><mo>=</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>λ</mi><mo>∝</mo><msup><mi>T</mi><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></math>"]}], "trap": "Use absolute temperature in kelvin. Doubling T halves the peak wavelength.", "image": "assets/q11.png", "graph": null, "note": null, "formulas": [{"name": "Wien’s displacement law", "equation": "λₚₑₐₖT = 2.90 × 10⁻³ m K", "symbols": "λ with subscript peak is the peak wavelength in metres; T is absolute temperature in kelvin. The rearranged versions are shown above.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mi>T</mi><mo>=</mo><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mspace width=\"0.2em\"/><mtext>m K</mtext></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub></mrow></mfrac></mrow></math>"]}]}, {"id": "m12", "title": "Mixing hot water and ice", "topic": "Heating", "q": "An equal mass of water and ice is mixed in a container and the container is sealed, so that it is thermally isolated from its surroundings. The ice is at a temperature of 0 °C and the water is at a temperature of 100 °C. The ice melts entirely.\n\nWhich of the following statements is correct about the system?", "options": ["The final temperature of the system will be 50 °C.", "The final temperature of the system will be less than 50 °C.", "The final temperature of the system will be more than 50 °C.", "The total internal energy of the system increases."], "answer": 1, "hint": "Some energy from the hot water is used for melting before the melted water warms.", "steps": [{"text": "The hot water loses energy. The ice needs energy to melt and then the melted ice warms to final temperature T. Both starting masses are the same, m.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mi>c</mi><mo>(</mo><mn>100</mn><mo>−</mo><mi>T</mi><mo>)</mo><mo>=</mo><mi>m</mi><mi>L</mi><mo>+</mo><mi>m</mi><mi>c</mi><mi>T</mi></mrow></math>"]}, {"text": "Divide EVERY term by m. The equal masses cancel.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>(</mo><mn>100</mn><mo>−</mo><mi>T</mi><mo>)</mo><mo>=</mo><mi>L</mi><mo>+</mo><mi>c</mi><mi>T</mi></mrow></math>"]}, {"text": "Expand the bracket: multiply c by both terms inside it.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>100</mn><mi>c</mi><mo>−</mo><mi>c</mi><mi>T</mi><mo>=</mo><mi>L</mi><mo>+</mo><mi>c</mi><mi>T</mi></mrow></math>"]}, {"text": "Add cT to both sides.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>100</mn><mi>c</mi><mo>=</mo><mi>L</mi><mo>+</mo><mn>2</mn><mi>c</mi><mi>T</mi></mrow></math>"]}, {"text": "Subtract L from both sides.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>100</mn><mi>c</mi><mo>−</mo><mi>L</mi><mo>=</mo><mn>2</mn><mi>c</mi><mi>T</mi></mrow></math>"]}, {"text": "Divide both sides by 2c.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>100</mn><mi>c</mi><mo>−</mo><mi>L</mi></mrow><mrow><mn>2</mn><mi>c</mi></mrow></mfrac><mo>=</mo><mn>50</mn><mo>−</mo><mfrac><mrow><mi>L</mi></mrow><mrow><mn>2</mn><mi>c</mi></mrow></mfrac></mrow></math>"]}, {"text": "The melting term is positive, so it is subtracted from 50 °C. Therefore the final temperature is below 50 °C. No values of c or L are needed to choose B.", "math": []}], "trap": "Do not simply average temperatures when a change of state occurs.", "image": "assets/q12.png", "graph": null, "note": null, "formulas": [{"name": "Conservation of energy", "equation": "Energy lost = energy gained", "symbols": "For these mixture calculations, add the energy for each stage: warming ice, melting ice and warming the melted water. Assume no energy exchange with the surroundings.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mrow><mtext>lost</mtext></mrow></msub><mo>=</mo><msub><mi>Q</mi><mrow><mtext>gained</mtext></mrow></msub></mrow></math>"]}, {"name": "Temperature change", "equation": "Q = mcΔT", "symbols": "Q = energy transferred (J); m = mass (kg); c = specific heat capacity (J kg⁻¹ K⁻¹); ΔT = temperature change (K).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"name": "Change of state", "equation": "Q = mL", "symbols": "Q = energy transferred (J); m = mass (kg); L = specific latent heat (J kg⁻¹). Temperature stays constant during the change of state.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>"]}]}, {"id": "m13", "title": "Condensing a gas", "topic": "Phase changes", "q": "What is true about the total intermolecular potential energy and the internal energy of a substance that changes from the gas state into the liquid state without a change in temperature?", "options": ["Potential energy decreases; internal energy unchanged", "Potential energy unchanged; internal energy decreases", "Potential energy decreases; internal energy decreases", "Both unchanged"], "answer": 2, "hint": "Condensation releases energy while the temperature remains constant.", "steps": ["Constant temperature means average kinetic energy stays constant.", "Intermolecular potential energy decreases as the gas condenses.", "Internal energy = total random kinetic energy + intermolecular potential energy.", "Therefore internal energy also decreases."], "trap": "Energy released during condensation is latent heat.", "image": "assets/q13.png", "graph": null, "note": null, "optionColumns": ["Total intermolecular potential energy", "Internal energy"], "optionRows": [["Decreases", "Unchanged"], ["Unchanged", "Decreases"], ["Decreases", "Decreases"], ["Unchanged", "Unchanged"]]}, {"id": "m14", "title": "Comparing cooling curves", "topic": "Heating", "q": "Substances A and B are initially in the gas state. The substances have the same mass. Energy is removed from the substances at a constant rate. The graph shows how the temperature of each substance varies with time.", "options": ["cA > cB; LA > LB", "cA > cB; LA < LB", "cA < cB; LA > LB", "cA < cB; LA < LB"], "answer": 2, "hint": "Look at the slopes after the flat sections, then compare the lengths of the flat sections.", "steps": [{"text": "First compare the sloping LIQUID sections after the plateaus. Use G for the positive size of the temperature–time gradient.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>G</mi><mo>=</mo><mo>|</mo><mfrac><mrow><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mo>|</mo></mrow></math>"]}, {"text": "Start with heating energy and power. For cooling, use the amount of energy removed and the size of the temperature drop.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mo>|</mo><mi>Δ</mi><mi>T</mi><mo>|</mo></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac></mrow></math>"]}, {"text": "Replace Q with mc|ΔT|, then recognise the gradient.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mi>m</mi><mi>c</mi><mfrac><mrow><mo>|</mo><mi>Δ</mi><mi>T</mi><mo>|</mo></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mo>=</mo><mi>m</mi><mi>c</mi><mi>G</mi></mrow></math>"]}, {"text": "To leave c on its own, divide BOTH sides by mG.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>P</mi></mrow><mrow><mi>m</mi><mi>G</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>m</mi><mi>c</mi><mi>G</mi></mrow><mrow><mi>m</mi><mi>G</mi></mrow></mfrac></mrow></math>"]}, {"text": "Cancel mG on the right.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mfrac><mrow><mi>P</mi></mrow><mrow><mi>m</mi><mi>G</mi></mrow></mfrac></mrow></math>"]}, {"text": "P and m are the same for both substances. A has the steeper liquid slope, so its G is bigger. A bigger number on the bottom makes the fraction smaller.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>G</mi><mi>A</mi></msub><mo>&gt;</mo><msub><mi>G</mi><mi>B</mi></msub></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>c</mi><mi>A</mi></msub><mo>&lt;</mo><msub><mi>c</mi><mi>B</mi></msub></mrow></math>"]}, {"text": "Now compare the plateaus. Use energy removed = power × time, and latent heat energy = mass × latent heat.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>P</mi><mi>t</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mi>t</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>"]}, {"text": "Divide BOTH sides by m, then cancel m on the right.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>P</mi><mi>t</mi></mrow><mrow><mi>m</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>m</mi><mi>L</mi></mrow><mrow><mi>m</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mi>t</mi></mrow><mrow><mi>m</mi></mrow></mfrac></mrow></math>"]}, {"text": "P and m are the same. A has the longer plateau, so t is bigger. A bigger number on the top makes L bigger.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>t</mi><mi>A</mi></msub><mo>&gt;</mo><msub><mi>t</mi><mi>B</mi></msub></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>L</mi><mi>A</mi></msub><mo>&gt;</mo><msub><mi>L</mi><mi>B</mi></msub></mrow></math>"]}, {"text": "Combine the two comparisons: the answer is C.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>c</mi><mi>A</mi></msub><mo>&lt;</mo><msub><mi>c</mi><mi>B</mi></msub><mspace width=\"1em\"/><msub><mi>L</mi><mi>A</mi></msub><mo>&gt;</mo><msub><mi>L</mi><mi>B</mi></msub></mrow></math>"]}], "trap": "For liquid heat capacity, compare the slopes after the plateaus, not the gas slopes before them.", "image": "assets/q14.png", "graph": "assets/q14-graph.png", "optionsImage": "assets/cooling-options.png", "note": null, "formulas": [{"name": "Cooling slope", "equation": "P = mc|ΔT/Δt|  →  c = P/(m|ΔT/Δt|)", "symbols": "P = rate of energy removal (W); m = mass (kg); G = magnitude of the temperature–time gradient (K s⁻¹). Use the positive size of the cooling slope.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>G</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>G</mi><mo>=</mo><mo>|</mo><mfrac><mrow><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac><mo>|</mo></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mfrac><mrow><mi>P</mi></mrow><mrow><mi>m</mi><mi>G</mi></mrow></mfrac></mrow></math>"]}, {"name": "Length of the plateau", "equation": "Pt = mL  →  L = Pt/m", "symbols": "P = rate of energy removal (W); t = time spent changing state (s); m = mass (kg); L = specific latent heat (J kg⁻¹). A longer plateau means a larger L when P and m are equal.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mi>t</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mi>t</mi></mrow><mrow><mi>m</mi></mrow></mfrac></mrow></math>"]}], "afterGraph": "How do the specific heat capacities in the liquid state and the specific latent heats of vaporization compare for the two substances?", "optionColumns": ["Specific heat capacities", "Specific latent heats of vaporization"], "optionRows": [["cₐ > cᵦ", "Lₐ > Lᵦ"], ["cₐ > cᵦ", "Lₐ < Lᵦ"], ["cₐ < cᵦ", "Lₐ > Lᵦ"], ["cₐ < cᵦ", "Lₐ < Lᵦ"]], "graphWidth": 490, "graphHeight": 325}, {"id": "m15", "title": "Properties of a black body", "topic": "Radiation", "q": "Three statements about a perfect black body are:\n\nI. It absorbs all the radiation that falls on it.\n\nII. At very low temperatures it appears black.\n\nIII. At very high temperatures it appears really bright.\n\nWhich of these statements are correct?", "options": ["I and II only", "I and III only", "II and III only", "I, II and III"], "answer": 3, "hint": "A perfect absorber is also an effective thermal emitter.", "steps": ["I is true: a perfect black body absorbs all incident radiation.", "II is true: at low temperatures it emits negligible visible light.", "III is true: at high temperatures it emits strongly, including visible light.", "All three statements are correct."], "trap": "“Black body” describes its absorption, not its colour at every temperature.", "image": "assets/q15.png", "graph": null, "note": null}, {"id": "m16", "title": "Thermal conductivity", "topic": "Energy transfer", "q": "Thermal energy is transferred through a copper rod at a rate of 800 W. The cross-sectional area of the rod is 0.010 m² and the length of the rod is 50 cm. There is a constant temperature difference of 100 K between the two ends of the rod.\n\nWhat is the thermal conductivity of copper?", "options": ["100 W m⁻¹ K⁻¹", "200 W m⁻¹ K⁻¹", "400 W m⁻¹ K⁻¹", "800 W m⁻¹ K⁻¹"], "answer": 2, "hint": "Use P = kAΔT/ℓ. Convert the length to metres.", "steps": [{"text": "Convert the length to metres.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>ℓ</mi><mo>=</mo><mfrac><mrow><mn>50</mn></mrow><mrow><mn>100</mn></mrow></mfrac><mo>=</mo><mn>0.50</mn><mspace width=\"0.2em\"/><mtext>m</mtext></mrow></math>"]}, {"text": "Start with the conduction equation.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mfrac><mrow><mi>k</mi><mi>A</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>ℓ</mi></mrow></mfrac></mrow></math>"]}, {"text": "Multiply BOTH sides by ℓ to remove the denominator.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mi>ℓ</mi><mo>=</mo><mi>k</mi><mi>A</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"text": "Divide BOTH sides by AΔT.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>P</mi><mi>ℓ</mi></mrow><mrow><mi>A</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>k</mi><mi>A</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>A</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "Cancel AΔT on the right and write k first.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>k</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mi>ℓ</mi></mrow><mrow><mi>A</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "Substitute the values.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>k</mi><mo>=</mo><mfrac><mrow><mn>800</mn><mo>×</mo><mn>0.50</mn></mrow><mrow><mn>0.010</mn><mo>×</mo><mn>100</mn></mrow></mfrac></mrow></math>"]}, {"text": "Calculate the top and bottom separately, then divide.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>k</mi><mo>=</mo><mfrac><mrow><mn>400</mn></mrow><mrow><mn>1.0</mn></mrow></mfrac><mo>=</mo><mn>400</mn><mspace width=\"0.2em\"/><msup><mtext>W m</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup><msup><mtext>K</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></math>"]}], "trap": "The given 800 W is already a rate of energy transfer; do not divide it by time again.", "image": "assets/q16.png", "graph": null, "note": null, "formulas": [{"name": "Thermal conduction", "equation": "P = kAΔT/ℓ  →  k = Pℓ/(AΔT)", "symbols": "P = rate of energy transfer (W); k = thermal conductivity (W m⁻¹ K⁻¹); A = cross-sectional area (m²); ΔT = temperature difference (K); ℓ = rod length (m).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mfrac><mrow><mi>k</mi><mi>A</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>ℓ</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>k</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mi>ℓ</mi></mrow><mrow><mi>A</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>"]}]}, {"id": "m17", "title": "Power from a temperature graph", "topic": "Heating", "q": "A heater supplies energy at a constant rate to 100 kg of water. The specific heat capacity of water is 4.2 kJ kg⁻¹ K⁻¹. The graph below shows how the temperature of the water varies with time. The gradient of the graph is 1/1000.", "options": ["4.2 × 10¹ W", "4.2 × 10² W", "4.2 × 10³ W", "4.2 × 10⁴ W"], "answer": 1, "hint": "Divide Q = mcΔT by time.", "steps": [{"text": "Convert the heat capacity from kJ to J.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mn>4.2</mn><mo>×</mo><mn>1000</mn><mo>=</mo><mn>4200</mn><mspace width=\"0.2em\"/><msup><mtext>J kg</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup><msup><mtext>K</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></math>"]}, {"text": "Write the heating equation and the definition of power.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac></mrow></math>"]}, {"text": "Substitute mcΔT in place of Q.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mfrac><mrow><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac></mrow></math>"]}, {"text": "Mass and specific heat capacity are constant, so write them outside the fraction.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mi>m</mi><mi>c</mi><mfrac><mrow><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac></mrow></math>"]}, {"text": "The fraction is the graph gradient. Insert all the values.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mn>100</mn><mo>×</mo><mn>4200</mn><mo>×</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>1000</mn></mrow></mfrac></mrow></math>"]}, {"text": "Multiply, then divide by 1000.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mfrac><mrow><mn>420000</mn></mrow><mrow><mn>1000</mn></mrow></mfrac><mo>=</mo><mn>420</mn><mspace width=\"0.2em\"/><mtext>W</mtext></mrow></math>"]}, {"text": "Write the answer in standard form.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mn>4.2</mn><mo>×</mo><msup><mn>10</mn><mn>2</mn></msup><mspace width=\"0.2em\"/><mtext>W</mtext></mrow></math>"]}], "trap": "The gradient tells you the temperature increase each second.", "image": "assets/q17.png", "graph": "assets/q17-graph.png", "note": null, "formulas": [{"name": "Temperature change", "equation": "Q = mcΔT", "symbols": "Q = energy transferred (J); m = mass (kg); c = specific heat capacity (J kg⁻¹ K⁻¹); ΔT = temperature change (K).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"name": "Energy from a heater", "equation": "P = Q/t  →  Q = Pt", "symbols": "P = power (W); Q = energy transferred (J); t = time (s).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>t</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>P</mi><mi>t</mi></mrow></math>"]}, {"name": "Power from the gradient", "equation": "P = mc(ΔT/Δt)", "symbols": "The fraction is the temperature change divided by the time taken: the graph gradient (K s⁻¹). Multiply mass × specific heat capacity × gradient.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mi>m</mi><mi>c</mi><mfrac><mrow><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>Δ</mi><mi>t</mi></mrow></mfrac></mrow></math>"]}], "afterGraph": "What is the power supplied by the heater?", "graphWidth": 280, "graphHeight": 215}, {"id": "m18", "title": "Ratio of c to L", "topic": "Heating", "q": "The specific heat capacity of a substance in the solid state is c and the specific latent heat of fusion of the substance is L. When 5000 J of energy is supplied to m kg of this substance in the solid state, the temperature of the substance increases by 50 K. When 20000 J of energy is supplied to m/2 kg of this substance in the solid state at its melting point, the substance completely melts without a change in its temperature. What is the ratio c/L?", "options": ["0.010 K", "0.0025 K", "0.010 K⁻¹", "0.0025 K⁻¹"], "answer": 3, "hint": "Write one expression for c and one for L; the unknown mass cancels.", "steps": [{"text": "Start with the heating equation for the whole mass m.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"text": "Divide BOTH sides by mΔT to make c the subject.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>m</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>m</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>m</mi><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "Insert the heating energy and temperature change, then simplify the numerical factor.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mfrac><mrow><mn>5000</mn></mrow><mrow><mi>m</mi><mo>×</mo><mn>50</mn></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>100</mn></mrow><mrow><mi>m</mi></mrow></mfrac></mrow></math>"]}, {"text": "Now use latent heat. Only HALF the mass melts in this stage.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mo>(</mo><mfrac><mrow><mi>m</mi></mrow><mrow><mn>2</mn></mrow></mfrac><mo>)</mo><mi>L</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>20000</mn><mo>=</mo><mo>(</mo><mfrac><mrow><mi>m</mi></mrow><mrow><mn>2</mn></mrow></mfrac><mo>)</mo><mi>L</mi></mrow></math>"]}, {"text": "Multiply BOTH sides by 2 to remove the half.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>40000</mn><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>"]}, {"text": "Divide BOTH sides by m.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mn>40000</mn></mrow><mrow><mi>m</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>m</mi><mi>L</mi></mrow><mrow><mi>m</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mfrac><mrow><mn>40000</mn></mrow><mrow><mi>m</mi></mrow></mfrac></mrow></math>"]}, {"text": "Put the expression for c on the top and the expression for L on the bottom.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>c</mi></mrow><mrow><mi>L</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mfrac><mrow><mn>100</mn></mrow><mrow><mi>m</mi></mrow></mfrac></mrow><mrow><mfrac><mrow><mn>40000</mn></mrow><mrow><mi>m</mi></mrow></mfrac></mrow></mfrac></mrow></math>"]}, {"text": "Dividing by a fraction means multiplying by its reciprocal.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>c</mi></mrow><mrow><mi>L</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>100</mn></mrow><mrow><mi>m</mi></mrow></mfrac><mo>×</mo><mfrac><mrow><mi>m</mi></mrow><mrow><mn>40000</mn></mrow></mfrac></mrow></math>"]}, {"text": "Cancel the mass m. Divide 100 by 40000.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>c</mi></mrow><mrow><mi>L</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>100</mn></mrow><mrow><mn>40000</mn></mrow></mfrac><mo>=</mo><mn>0.0025</mn></mrow></math>"]}, {"text": "Divide the units too: joules and kilograms cancel, leaving per kelvin.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><msup><mtext>J kg</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup><msup><mtext>K</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow><mrow><msup><mtext>J kg</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></mfrac><mo>=</mo><msup><mtext>K</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>c</mi></mrow><mrow><mi>L</mi></mrow></mfrac><mo>=</mo><mn>0.0025</mn><mspace width=\"0.2em\"/><msup><mtext>K</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></math>"]}], "trap": "Melting uses half the mass, so divide 20 000 by m/2, not by m.", "image": "assets/q18.png", "graph": null, "note": null, "formulas": [{"name": "Temperature change", "equation": "Q = mcΔT", "symbols": "Q = energy transferred (J); m = mass (kg); c = specific heat capacity (J kg⁻¹ K⁻¹); ΔT = temperature change (K).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"name": "Change of state", "equation": "Q = mL", "symbols": "Q = energy transferred (J); m = mass (kg); L = specific latent heat (J kg⁻¹). Temperature stays constant during the change of state.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>"]}, {"name": "Rearrange each equation", "equation": "c = Qₕ/(mₕΔT)     L = Qₘ/mₘ", "symbols": "Use the mass belonging to each stage. The heated mass is m; the mass that melts is half of m.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mfrac><mrow><msub><mi>Q</mi><mrow><mtext>heating</mtext></mrow></msub></mrow><mrow><msub><mi>m</mi><mrow><mtext>heating</mtext></mrow></msub><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mfrac><mrow><msub><mi>Q</mi><mrow><mtext>melting</mtext></mrow></msub></mrow><mrow><msub><mi>m</mi><mrow><mtext>melting</mtext></mrow></msub></mrow></mfrac></mrow></math>"]}]}, {"id": "m19", "title": "Comparing star radii", "topic": "Radiation", "q": "The surface temperature of star P is twice the surface temperature of star Q and its luminosity is four times the luminosity of star Q.\n\nWhat is (radius of star Q)/(radius of star P)?", "options": ["1/2", "1/√2", "2", "√2"], "answer": 2, "hint": "For a spherical black body, luminosity is proportional to R²T⁴.", "steps": [{"text": "For a spherical black-body star, write the luminosity law for each star.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>L</mi><mi>P</mi></msub><mo>=</mo><mn>4</mn><mi>π</mi><msup><msub><mi>R</mi><mi>P</mi></msub><mn>2</mn></msup><mi>σ</mi><msup><msub><mi>T</mi><mi>P</mi></msub><mn>4</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>L</mi><mi>Q</mi></msub><mo>=</mo><mn>4</mn><mi>π</mi><msup><msub><mi>R</mi><mi>Q</mi></msub><mn>2</mn></msup><mi>σ</mi><msup><msub><mi>T</mi><mi>Q</mi></msub><mn>4</mn></msup></mrow></math>"]}, {"text": "Divide the first equation by the second. The shared 4π and σ factors cancel.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><msub><mi>L</mi><mi>P</mi></msub></mrow><mrow><msub><mi>L</mi><mi>Q</mi></msub></mrow></mfrac><mo>=</mo><mfrac><mrow><msup><msub><mi>R</mi><mi>P</mi></msub><mn>2</mn></msup><msup><msub><mi>T</mi><mi>P</mi></msub><mn>4</mn></msup></mrow><mrow><msup><msub><mi>R</mi><mi>Q</mi></msub><mn>2</mn></msup><msup><msub><mi>T</mi><mi>Q</mi></msub><mn>4</mn></msup></mrow></mfrac></mrow></math>"]}, {"text": "Write this as a product of two ratios.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><msub><mi>L</mi><mi>P</mi></msub></mrow><mrow><msub><mi>L</mi><mi>Q</mi></msub></mrow></mfrac><mo>=</mo><mo>(</mo><mfrac><mrow><msub><mi>R</mi><mi>P</mi></msub></mrow><mrow><msub><mi>R</mi><mi>Q</mi></msub></mrow></mfrac><msup><mo>)</mo><mn>2</mn></msup><mo>(</mo><mfrac><mrow><msub><mi>T</mi><mi>P</mi></msub></mrow><mrow><msub><mi>T</mi><mi>Q</mi></msub></mrow></mfrac><msup><mo>)</mo><mn>4</mn></msup></mrow></math>"]}, {"text": "Insert the luminosity ratio 4 and the temperature ratio 2.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>4</mn><mo>=</mo><mo>(</mo><mfrac><mrow><msub><mi>R</mi><mi>P</mi></msub></mrow><mrow><msub><mi>R</mi><mi>Q</mi></msub></mrow></mfrac><msup><mo>)</mo><mn>2</mn></msup><mo>×</mo><msup><mn>2</mn><mn>4</mn></msup></mrow></math>"]}, {"text": "Work out 2 to the power 4.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>4</mn><mo>=</mo><mn>16</mn><mo>(</mo><mfrac><mrow><msub><mi>R</mi><mi>P</mi></msub></mrow><mrow><msub><mi>R</mi><mi>Q</mi></msub></mrow></mfrac><msup><mo>)</mo><mn>2</mn></msup></mrow></math>"]}, {"text": "Divide BOTH sides by 16.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mn>4</mn></mrow><mrow><mn>16</mn></mrow></mfrac><mo>=</mo><mo>(</mo><mfrac><mrow><msub><mi>R</mi><mi>P</mi></msub></mrow><mrow><msub><mi>R</mi><mi>Q</mi></msub></mrow></mfrac><msup><mo>)</mo><mn>2</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mn>1</mn></mrow><mrow><mn>4</mn></mrow></mfrac><mo>=</mo><mo>(</mo><mfrac><mrow><msub><mi>R</mi><mi>P</mi></msub></mrow><mrow><msub><mi>R</mi><mi>Q</mi></msub></mrow></mfrac><msup><mo>)</mo><mn>2</mn></msup></mrow></math>"]}, {"text": "Take the positive square root of BOTH sides, because radii are positive.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msqrt><mrow><mfrac><mrow><mn>1</mn></mrow><mrow><mn>4</mn></mrow></mfrac></mrow></msqrt><mo>=</mo><mfrac><mrow><msub><mi>R</mi><mi>P</mi></msub></mrow><mrow><msub><mi>R</mi><mi>Q</mi></msub></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><msub><mi>R</mi><mi>P</mi></msub></mrow><mrow><msub><mi>R</mi><mi>Q</mi></msub></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>1</mn></mrow><mrow><mn>2</mn></mrow></mfrac></mrow></math>"]}, {"text": "The question wants the opposite ratio. Turn BOTH fractions upside down.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><msub><mi>R</mi><mi>Q</mi></msub></mrow><mrow><msub><mi>R</mi><mi>P</mi></msub></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>2</mn></mrow><mrow><mn>1</mn></mrow></mfrac><mo>=</mo><mn>2</mn></mrow></math>"]}], "trap": "Check the order of the radius ratio before choosing an option.", "image": "assets/q19.png", "graph": null, "note": null, "formulas": [{"name": "Stefan–Boltzmann law", "equation": "L = σAT⁴ = 4πR²σT⁴", "symbols": "L = luminosity (W); A = surface area (m²); R = star radius (m); T = temperature (K); σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴. For a sphere, A = 4πR².", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mi>σ</mi><mi>A</mi><msup><mi>T</mi><mn>4</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>A</mi><mo>=</mo><mn>4</mn><mi>π</mi><msup><mi>R</mi><mn>2</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mn>4</mn><mi>π</mi><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow></math>"]}, {"name": "Compare two stars", "equation": "L_P/L_Q = (R_P/R_Q)²(T_P/T_Q)⁴", "symbols": "The shared constants 4π and σ cancel when dividing the luminosities. P and Q label the two stars; they are not powers or energies here.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><msub><mi>L</mi><mi>P</mi></msub></mrow><mrow><msub><mi>L</mi><mi>Q</mi></msub></mrow></mfrac><mo>=</mo><mo>(</mo><mfrac><mrow><msub><mi>R</mi><mi>P</mi></msub></mrow><mrow><msub><mi>R</mi><mi>Q</mi></msub></mrow></mfrac><msup><mo>)</mo><mn>2</mn></msup><mo>(</mo><mfrac><mrow><msub><mi>T</mi><mi>P</mi></msub></mrow><mrow><msub><mi>T</mi><mi>Q</mi></msub></mrow></mfrac><msup><mo>)</mo><mn>4</mn></msup></mrow></math>"]}]}, {"id": "m20", "title": "Colour at the peak wavelength", "topic": "Radiation", "q": "The temperature of a black body is 7000 K.\n\nWhat is the colour of the light radiated by the black body at its peak wavelength?", "options": ["Green", "Red", "Yellow", "Violet"], "answer": 3, "hint": "Find λ using λT = 2.90 × 10⁻³ m K, then convert metres to nm.", "steps": [{"text": "Start with Wien’s law.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mi>T</mi><mo>=</mo><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow></math>"]}, {"text": "Divide BOTH sides by T.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mi>T</mi></mrow><mrow><mi>T</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "Cancel T on the left.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>"]}, {"text": "Insert 7000 K and calculate.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><mn>7000</mn></mrow></mfrac><mo>=</mo><mn>4.14</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>7</mn></mrow></msup><mspace width=\"0.2em\"/><mtext>m</mtext></mrow></math>"]}, {"text": "Convert metres to nanometres by multiplying by one billion.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mo>=</mo><mn>4.14</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>7</mn></mrow></msup><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup><mo>=</mo><mn>414</mn><mspace width=\"0.2em\"/><mtext>nm</mtext></mrow></math>"]}, {"text": "414 nm is violet. This is the colour at the peak wavelength, not the overall colour of all the emitted light.", "math": []}], "trap": "The colour of the peak wavelength is not the overall perceived colour of the object, which emits many wavelengths.", "image": "assets/q20.png", "graph": null, "note": null, "formulas": [{"name": "Wien’s displacement law", "equation": "λₚₑₐₖT = 2.90 × 10⁻³ m K", "symbols": "λ with subscript peak is the peak wavelength in metres; T is absolute temperature in kelvin. The rearranged versions are shown above.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mi>T</mi><mo>=</mo><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mspace width=\"0.2em\"/><mtext>m K</mtext></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub></mrow></mfrac></mrow></math>"]}]}, {"id": "m21", "title": "Heating two identical flasks", "topic": "Heating", "q": "A flask contains 500 g of a liquid. When energy is supplied to the flask using a heater with a power rating of 200 W during a minute, the temperature of the flask and the liquid changes by 20 K. When energy is supplied using the same heater to an identical flask containing 1500 g of the same liquid, the heater must be used for two minutes to achieve the same temperature change. What is the specific heat capacity of the liquid?", "options": ["0.30 kJ kg⁻¹ K⁻¹", "0.60 kJ kg⁻¹ K⁻¹", "3.0 kJ kg⁻¹ K⁻¹", "6.0 kJ kg⁻¹ K⁻¹"], "answer": 1, "hint": "Subtract the two trials to cancel the energy used to warm the identical flasks.", "steps": [{"text": "Let F be the energy used to warm one flask. Both identical flasks have the same temperature rise, so F is the same in both trials.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mi>t</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi><mo>+</mo><mi>F</mi></mrow></math>"]}, {"text": "Convert the times to seconds and find each trial’s supplied energy.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo>=</mo><mn>200</mn><mo>×</mo><mn>60</mn><mo>=</mo><mn>12000</mn><mspace width=\"0.2em\"/><mtext>J</mtext></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mn>2</mn></msub><mo>=</mo><mn>200</mn><mo>×</mo><mn>120</mn><mo>=</mo><mn>24000</mn><mspace width=\"0.2em\"/><mtext>J</mtext></mrow></math>"]}, {"text": "Convert the liquid masses to kg and write the two energy equations.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>12000</mn><mo>=</mo><mn>0.500</mn><mi>c</mi><mo>×</mo><mn>20</mn><mo>+</mo><mi>F</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>24000</mn><mo>=</mo><mn>1.500</mn><mi>c</mi><mo>×</mo><mn>20</mn><mo>+</mo><mi>F</mi></mrow></math>"]}, {"text": "Subtract the FIRST equation from the SECOND. Subtract each term on the right as well as the left.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>24000</mn><mo>−</mo><mn>12000</mn><mo>=</mo><mo>(</mo><mn>1.500</mn><mo>−</mo><mn>0.500</mn><mo>)</mo><mi>c</mi><mo>×</mo><mn>20</mn><mo>+</mo><mo>(</mo><mi>F</mi><mo>−</mo><mi>F</mi><mo>)</mo></mrow></math>"]}, {"text": "The flask terms cancel. Simplify the mass difference.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>12000</mn><mo>=</mo><mn>1.000</mn><mi>c</mi><mo>×</mo><mn>20</mn></mrow></math>"]}, {"text": "Divide BOTH sides by the mass difference multiplied by the temperature rise.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mn>12000</mn></mrow><mrow><mn>1.000</mn><mo>×</mo><mn>20</mn></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>1.000</mn><mi>c</mi><mo>×</mo><mn>20</mn></mrow><mrow><mn>1.000</mn><mo>×</mo><mn>20</mn></mrow></mfrac></mrow></math>"]}, {"text": "Cancel the factors on the right and calculate.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mfrac><mrow><mn>12000</mn></mrow><mrow><mn>20</mn></mrow></mfrac><mo>=</mo><mn>600</mn><mspace width=\"0.2em\"/><msup><mtext>J kg</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup><msup><mtext>K</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></math>"]}, {"text": "Convert J to kJ by dividing by 1000.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mfrac><mrow><mn>600</mn></mrow><mrow><mn>1000</mn></mrow></mfrac><mo>=</mo><mn>0.60</mn><mspace width=\"0.2em\"/><msup><mtext>kJ kg</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup><msup><mtext>K</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></math>"]}], "trap": "Using just one trial would include energy used to heat the flask. Assume negligible energy losses.", "image": "assets/q21.png", "graph": null, "note": null, "formulas": [{"name": "Energy from a heater", "equation": "P = Q/t  →  Q = Pt", "symbols": "P = power (W); Q = energy transferred (J); t = time (s).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>P</mi><mo>=</mo><mfrac><mrow><mi>Q</mi></mrow><mrow><mi>t</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>P</mi><mi>t</mi></mrow></math>"]}, {"name": "Temperature change", "equation": "Q = mcΔT", "symbols": "Q = energy transferred (J); m = mass (kg); c = specific heat capacity (J kg⁻¹ K⁻¹); ΔT = temperature change (K).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"name": "Subtract the two trials", "equation": "ΔQ = Δm × c × ΔT  →  c = ΔQ/(Δm × ΔT)", "symbols": "ΔQ = difference between the trial energies (J); Δm = difference between liquid masses (kg); ΔT = the same temperature rise in each trial (K). The identical flask terms cancel.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Δ</mi><mi>Q</mi><mo>=</mo><mi>Δ</mi><mi>m</mi><mspace width=\"0.2em\"/><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mfrac><mrow><mi>Δ</mi><mi>Q</mi></mrow><mrow><mi>Δ</mi><mi>m</mi><mspace width=\"0.2em\"/><mi>Δ</mi><mi>T</mi></mrow></mfrac></mrow></math>"]}]}];
const PAPERS = [{"id": "ice", "title": "Ice cubes in water", "topic": "Energy balance · Phase changes", "image": "assets/q22.png", "intro": "A student carries out an experiment to determine the specific latent heat of fusion of ice. She drops five ice cubes into a container filled with water. The following data is available for the experiment: Initial temperature of the ice cubes: −5.0 °C. Initial temperature of the water: 32 °C. Final temperature of the water: 14 °C. Mass of water: 520 g. Specific heat capacity of water: 4.2 kJ kg⁻¹ K⁻¹. Specific heat capacity of ice: 2.1 kJ kg⁻¹ K⁻¹. Estimated value of specific latent heat of fusion of ice based on the experiment: 0.37 MJ kg⁻¹.", "parts": [{"id": "ia", "label": "a", "q": "Distinguish between specific heat capacity and specific latent heat.", "marks": 2, "hint": "Think about what happens to 1 kg: a temperature rise or a change of state?", "answer": "Specific heat capacity: energy needed to raise the temperature of 1 kg by 1 K. Specific latent heat: energy needed to change the state of 1 kg without changing its temperature.", "steps": ["Specific heat capacity uses Q = mcΔT and has units J kg⁻¹ K⁻¹.", "Specific latent heat uses Q = mL and has units J kg⁻¹."], "check": ["Define both per kilogram.", "Mention 1 K for c and constant temperature for L."], "promptImage": "assets/ia-prompt.png", "formulas": [{"name": "Temperature change", "equation": "Q = mcΔT", "symbols": "Q = energy transferred (J); m = mass (kg); c = specific heat capacity (J kg⁻¹ K⁻¹); ΔT = temperature change (K).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"name": "Change of state", "equation": "Q = mL", "symbols": "Q = energy transferred (J); m = mass (kg); L = specific latent heat (J kg⁻¹). Temperature stays constant during the change of state.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>"]}]}, {"id": "ib1", "label": "b(i)", "q": "After carrying out the experiment, the student realizes that she did not measure the mass of the ice cubes. i. Find an estimate for the mass of one ice cube. Give your answer to an appropriate number of significant figures.", "marks": 5, "hint": "Energy lost by the warm water heats the ice to 0 °C, melts it, then warms the melted water to 14 °C.", "answer": "Mass of one cube ≈ 0.018 kg = 18 g (2 s.f.).", "steps": [{"text": "Let M be the total mass of all five ice cubes. Use joules, kilograms and kelvin temperature changes.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>c</mi><mi>w</mi></msub><mo>=</mo><mn>4200</mn><mspace width=\"1em\"/><msub><mi>c</mi><mi>i</mi></msub><mo>=</mo><mn>2100</mn><mspace width=\"1em\"/><mi>L</mi><mo>=</mo><mn>370000</mn></mrow></math>"]}, {"text": "Find the energy lost by the original warm water.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mrow><mtext>lost</mtext></mrow></msub><mo>=</mo><msub><mi>m</mi><mi>w</mi></msub><msub><mi>c</mi><mi>w</mi></msub><mi>Δ</mi><mi>T</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mrow><mtext>lost</mtext></mrow></msub><mo>=</mo><mn>0.520</mn><mo>×</mo><mn>4200</mn><mo>×</mo><mo>(</mo><mn>32</mn><mo>−</mo><mn>14</mn><mo>)</mo><mo>=</mo><mn>39312</mn><mspace width=\"0.2em\"/><mtext>J</mtext></mrow></math>"]}, {"text": "Stage 1: warm the ice from −5 °C to 0 °C.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo>=</mo><mi>M</mi><msub><mi>c</mi><mi>i</mi></msub><mo>(</mo><mn>0</mn><mo>−</mo><mo>(</mo><mo>−</mo><mn>5</mn><mo>)</mo><mo>)</mo></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo>=</mo><mi>M</mi><mo>×</mo><mn>2100</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>10500</mn><mi>M</mi></mrow></math>"]}, {"text": "Stage 2: melt all the ice.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mn>2</mn></msub><mo>=</mo><mi>M</mi><mi>L</mi><mo>=</mo><mn>370000</mn><mi>M</mi></mrow></math>"]}, {"text": "Stage 3: warm the melted ice from 0 °C to 14 °C.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mn>3</mn></msub><mo>=</mo><mi>M</mi><msub><mi>c</mi><mi>w</mi></msub><mo>(</mo><mn>14</mn><mo>−</mo><mn>0</mn><mo>)</mo></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mn>3</mn></msub><mo>=</mo><mi>M</mi><mo>×</mo><mn>4200</mn><mo>×</mo><mn>14</mn><mo>=</mo><mn>58800</mn><mi>M</mi></mrow></math>"]}, {"text": "Set the energy lost equal to the sum of the three gains.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>39312</mn><mo>=</mo><mn>10500</mn><mi>M</mi><mo>+</mo><mn>370000</mn><mi>M</mi><mo>+</mo><mn>58800</mn><mi>M</mi></mrow></math>"]}, {"text": "Factor out M, which appears in EVERY term on the right.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>39312</mn><mo>=</mo><mi>M</mi><mo>(</mo><mn>10500</mn><mo>+</mo><mn>370000</mn><mo>+</mo><mn>58800</mn><mo>)</mo></mrow></math>"]}, {"text": "Add the numbers inside the bracket.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>39312</mn><mo>=</mo><mn>439300</mn><mi>M</mi></mrow></math>"]}, {"text": "Divide BOTH sides by 439300.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mn>39312</mn></mrow><mrow><mn>439300</mn></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>439300</mn><mi>M</mi></mrow><mrow><mn>439300</mn></mrow></mfrac></mrow></math>"]}, {"text": "Cancel 439300 on the right. This gives the mass of ALL five cubes.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>M</mi><mo>=</mo><mfrac><mrow><mn>39312</mn></mrow><mrow><mn>439300</mn></mrow></mfrac><mo>=</mo><mn>0.0894878</mn><mspace width=\"0.2em\"/><mtext>kg</mtext></mrow></math>"]}, {"text": "Divide the total mass by five to get ONE cube.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>m</mi><mrow><mtext>one cube</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mi>M</mi></mrow><mrow><mn>5</mn></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>0.0894878</mn></mrow><mrow><mn>5</mn></mrow></mfrac><mo>=</mo><mn>0.0178976</mn><mspace width=\"0.2em\"/><mtext>kg</mtext></mrow></math>"]}, {"text": "Round to two significant figures. Multiply kg by 1000 to express the result in grams.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>m</mi><mrow><mtext>one cube</mtext></mrow></msub><mo>=</mo><mn>0.018</mn><mspace width=\"0.2em\"/><mtext>kg</mtext><mo>=</mo><mn>18</mn><mspace width=\"0.2em\"/><mtext>g</mtext></mrow></math>"]}], "check": ["Include all three stages for the ice.", "Divide the total ice mass by five."], "promptImage": "assets/ib1-prompt.png", "formulas": [{"name": "Conservation of energy", "equation": "Energy lost = energy gained", "symbols": "For these mixture calculations, add the energy for each stage: warming ice, melting ice and warming the melted water. Assume no energy exchange with the surroundings.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mrow><mtext>lost</mtext></mrow></msub><mo>=</mo><msub><mi>Q</mi><mrow><mtext>gained</mtext></mrow></msub></mrow></math>"]}, {"name": "Temperature change", "equation": "Q = mcΔT", "symbols": "Q = energy transferred (J); m = mass (kg); c = specific heat capacity (J kg⁻¹ K⁻¹); ΔT = temperature change (K).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"name": "Change of state", "equation": "Q = mL", "symbols": "Q = energy transferred (J); m = mass (kg); L = specific latent heat (J kg⁻¹). Temperature stays constant during the change of state.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>"]}, {"name": "Energy balance for the five cubes", "equation": "m_water c_water (T_initial − T_final) = Mc_ice (0 − T_ice) + ML + Mc_water (T_final − 0)", "symbols": "m_w = initial warm-water mass; M = total ice mass; c_w and c_i = specific heat capacities of water and ice; T_i and T_f = initial and final water temperatures; T_ice = initial ice temperature. Temperature differences may be in K or °C.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mrow><mtext>lost</mtext></mrow></msub><mo>=</mo><msub><mi>Q</mi><mrow><mtext>warm ice</mtext></mrow></msub><mo>+</mo><msub><mi>Q</mi><mrow><mtext>melt</mtext></mrow></msub><mo>+</mo><msub><mi>Q</mi><mrow><mtext>warm meltwater</mtext></mrow></msub></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>m</mi><mi>w</mi></msub><msub><mi>c</mi><mi>w</mi></msub><mo>(</mo><msub><mi>T</mi><mi>i</mi></msub><mo>−</mo><msub><mi>T</mi><mi>f</mi></msub><mo>)</mo><mo>=</mo><mi>M</mi><msub><mi>c</mi><mi>i</mi></msub><mo>(</mo><mn>0</mn><mo>−</mo><msub><mi>T</mi><mrow><mtext>ice</mtext></mrow></msub><mo>)</mo><mo>+</mo><mi>M</mi><mi>L</mi><mo>+</mo><mi>M</mi><msub><mi>c</mi><mi>w</mi></msub><msub><mi>T</mi><mi>f</mi></msub></mrow></math>"]}]}, {"id": "ib2", "label": "b(ii)", "q": "ii. State and explain why the value of the specific latent heat of fusion of ice based on the student's calculations is an estimate.", "marks": 2, "hint": "What else could exchange energy besides the original water and ice?", "answer": "The calculation assumes all energy lost by the original water is gained by the ice. In reality, the container and surroundings can also exchange energy, so the energy balance is approximate.", "steps": ["The container may cool and give energy to the mixture.", "Energy can also enter or leave through the surroundings.", "Ignoring these transfers changes the inferred latent heat. The direction depends on the actual energy transfers."], "check": ["Name an ignored energy transfer.", "Explain why it changes the calculated energy for melting."], "promptImage": "assets/ib2-prompt.png"}, {"id": "ic1", "label": "c(i)", "q": "In a similar experiment the same amount of crushed ice is used. Suggest how using crushed ice affects: i. The time taken for the ice to completely melt.", "marks": 1, "hint": "Compare the total exposed surface area.", "answer": "It melts in less time.", "steps": ["Crushed ice has a larger total surface area in contact with the water.", "Energy transfers to it faster, so it melts sooner."], "check": ["State shorter time and link to greater surface area."], "promptImage": "assets/ic1-prompt.png"}, {"id": "ic2", "label": "c(ii)", "q": "ii. The estimated value of the specific latent heat of fusion of ice.", "marks": 1, "hint": "Does changing the size of the pieces change the energy needed to melt each kilogram?", "answer": "Ideally, the value is unchanged. In a real experiment, faster melting can reduce unwanted energy exchange and make the estimate more accurate.", "steps": ["Latent heat is a property of the substance; breaking the ice does not change it.", "A shorter experiment can reduce energy exchange with the surroundings.", "Do not claim it must increase or decrease: that requires knowing the direction of the unwanted energy transfer. Assume the crushed ice has the same initial temperature and no extra surface water."], "check": ["Separate the unchanged physical property from experimental accuracy."], "promptImage": "assets/ic2-prompt.png"}], "introImage": "assets/ice-intro.png"}, {"id": "star", "title": "Reading a star’s spectrum", "topic": "Wien’s law · Luminosity", "image": "assets/q23.png", "graph": "assets/q23-graph.png", "intro": "The graph shows the black-body spectrum for a star. Relative intensity against wavelength / nm.", "parts": [{"id": "sa", "label": "a", "q": "Show that the surface temperature is about 6000 K.", "marks": 1, "hint": "Read the wavelength at the highest point of the curve, not its longest wavelength.", "answer": "T ≈ 6000 K.", "steps": [{"text": "Read the wavelength at the highest point of the graph: approximately 480 nm.", "math": []}, {"text": "Convert nanometres to metres.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mo>=</mo><mn>480</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>9</mn></mrow></msup><mo>=</mo><mn>4.80</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>7</mn></mrow></msup><mspace width=\"0.2em\"/><mtext>m</mtext></mrow></math>"]}, {"text": "Start with Wien’s law.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mi>T</mi><mo>=</mo><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow></math>"]}, {"text": "Divide BOTH sides by the peak wavelength.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mi>T</mi></mrow><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub></mrow></mfrac></mrow></math>"]}, {"text": "Cancel the wavelength factor on the left.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub></mrow></mfrac></mrow></math>"]}, {"text": "Substitute the graph reading and calculate.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><mn>4.80</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>7</mn></mrow></msup></mrow></mfrac><mo>=</mo><mn>6042</mn><mspace width=\"0.2em\"/><mtext>K</mtext></mrow></math>"]}, {"text": "This is about 6000 K. A graph reading of 500 nm gives 5800 K, also about 6000 K.", "math": []}], "check": ["Read the peak.", "Convert nm to m before substituting."], "promptImage": "assets/sa-prompt.png", "formulas": [{"name": "Wien’s displacement law", "equation": "λₚₑₐₖT = 2.90 × 10⁻³ m K", "symbols": "λ with subscript peak is the peak wavelength in metres; T is absolute temperature in kelvin. The rearranged versions are shown above.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mi>T</mi><mo>=</mo><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mspace width=\"0.2em\"/><mtext>m K</mtext></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub></mrow></mfrac></mrow></math>"]}]}, {"id": "sb", "label": "b", "q": "The radius of the star is 2.3 × 10⁶ km and its apparent brightness is 1.4 × 10⁻¹¹ W m⁻². (b) Estimate the distance of the star from Earth.", "marks": 3, "hint": "Combine L = 4πR²σT⁴ with apparent brightness b = L/(4πd²).", "answer": "d ≈ 5.3 × 10¹⁸ m (using T = 6000 K).", "steps": [{"text": "Convert the star’s radius from kilometres to metres. Use the approximate 6000 K temperature from part (a).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>R</mi><mo>=</mo><mn>2.3</mn><mo>×</mo><msup><mn>10</mn><mn>6</mn></msup><mo>×</mo><msup><mn>10</mn><mn>3</mn></msup><mo>=</mo><mn>2.3</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup><mspace width=\"0.2em\"/><mtext>m</mtext></mrow></math>"]}, {"text": "Write the luminosity and apparent-brightness equations.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mn>4</mn><mi>π</mi><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>b</mi><mo>=</mo><mfrac><mrow><mi>L</mi></mrow><mrow><mn>4</mn><mi>π</mi><msup><mi>d</mi><mn>2</mn></msup></mrow></mfrac></mrow></math>"]}, {"text": "Replace L in the brightness equation with the luminosity expression.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>b</mi><mo>=</mo><mfrac><mrow><mn>4</mn><mi>π</mi><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><mn>4</mn><mi>π</mi><msup><mi>d</mi><mn>2</mn></msup></mrow></mfrac></mrow></math>"]}, {"text": "Cancel the common factor 4π from the top and bottom.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>b</mi><mo>=</mo><mfrac><mrow><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><msup><mi>d</mi><mn>2</mn></msup></mrow></mfrac></mrow></math>"]}, {"text": "Multiply BOTH sides by d².", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>b</mi><msup><mi>d</mi><mn>2</mn></msup><mo>=</mo><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow></math>"]}, {"text": "Divide BOTH sides by b to leave d² on its own.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>b</mi><msup><mi>d</mi><mn>2</mn></msup></mrow><mrow><mi>b</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><mi>b</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msup><mi>d</mi><mn>2</mn></msup><mo>=</mo><mfrac><mrow><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><mi>b</mi></mrow></mfrac></mrow></math>"]}, {"text": "Take the positive square root of BOTH sides.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>d</mi><mo>=</mo><msqrt><mrow><mfrac><mrow><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><mi>b</mi></mrow></mfrac></mrow></msqrt></mrow></math>"]}, {"text": "Since the radius R is positive, the square root of R² is R. Take it outside the square root.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>d</mi><mo>=</mo><mi>R</mi><msqrt><mrow><mfrac><mrow><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><mi>b</mi></mrow></mfrac></mrow></msqrt></mrow></math>"]}, {"text": "Substitute the radius, constant, temperature and brightness.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>d</mi><mo>=</mo><mo>(</mo><mn>2.3</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup><mo>)</mo><msqrt><mrow><mfrac><mrow><mo>(</mo><mn>5.67</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>8</mn></mrow></msup><mo>)</mo><mo>×</mo><msup><mn>6000</mn><mn>4</mn></msup></mrow><mrow><mn>1.4</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>11</mn></mrow></msup></mrow></mfrac></mrow></msqrt></mrow></math>"]}, {"text": "Work out the power of four, then multiply by σ.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msup><mn>6000</mn><mn>4</mn></msup><mo>=</mo><mn>1.296</mn><mo>×</mo><msup><mn>10</mn><mrow><mn>15</mn></mrow></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup><mo>=</mo><mn>7.34832</mn><mo>×</mo><msup><mn>10</mn><mn>7</mn></msup></mrow></math>"]}, {"text": "Divide by the brightness, then take the square root.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><mi>b</mi></mrow></mfrac><mo>=</mo><mn>5.2488</mn><mo>×</mo><msup><mn>10</mn><mrow><mn>18</mn></mrow></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msqrt><mrow><mn>5.2488</mn><mo>×</mo><msup><mn>10</mn><mrow><mn>18</mn></mrow></msup></mrow></msqrt><mo>=</mo><mn>2.29103</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup></mrow></math>"]}, {"text": "Multiply by R and round to two significant figures.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>d</mi><mo>=</mo><mo>(</mo><mn>2.3</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup><mo>)</mo><mo>(</mo><mn>2.29103</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup><mo>)</mo></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>d</mi><mo>=</mo><mn>5.26936</mn><mo>×</mo><msup><mn>10</mn><mrow><mn>18</mn></mrow></msup><mspace width=\"0.2em\"/><mtext>m</mtext><mo>≈</mo><mn>5.3</mn><mo>×</mo><msup><mn>10</mn><mrow><mn>18</mn></mrow></msup><mspace width=\"0.2em\"/><mtext>m</mtext></mrow></math>"]}], "check": ["Convert km to m.", "Use kelvin and take the square root after rearranging."], "promptImage": "assets/sb-prompt.png", "formulas": [{"name": "Stefan–Boltzmann law", "equation": "L = σAT⁴ = 4πR²σT⁴", "symbols": "L = luminosity (W); A = surface area (m²); R = star radius (m); T = temperature (K); σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴. For a sphere, A = 4πR².", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mi>σ</mi><mi>A</mi><msup><mi>T</mi><mn>4</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>A</mi><mo>=</mo><mn>4</mn><mi>π</mi><msup><mi>R</mi><mn>2</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>L</mi><mo>=</mo><mn>4</mn><mi>π</mi><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow></math>"]}, {"name": "Apparent brightness", "equation": "b = L/(4πd²)", "symbols": "b = apparent brightness at Earth (W m⁻²); L = luminosity (W); d = distance from the star (m).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>b</mi><mo>=</mo><mfrac><mrow><mi>L</mi></mrow><mrow><mn>4</mn><mi>π</mi><msup><mi>d</mi><mn>2</mn></msup></mrow></mfrac></mrow></math>"]}, {"name": "Combine and rearrange", "equation": "b = R²σT⁴/d²  →  d = R√(σT⁴/b)", "symbols": "Substitute the radius in metres and temperature in kelvin. The 4π terms cancel when combining the two laws.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>b</mi><mo>=</mo><mfrac><mrow><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><msup><mi>d</mi><mn>2</mn></msup></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>d</mi><mo>=</mo><msqrt><mrow><mfrac><mrow><msup><mi>R</mi><mn>2</mn></msup><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><mi>b</mi></mrow></mfrac></mrow></msqrt><mo>=</mo><mi>R</mi><msqrt><mrow><mfrac><mrow><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow><mrow><mi>b</mi></mrow></mfrac></mrow></msqrt></mrow></math>"]}]}, {"id": "sc", "label": "c", "q": "The surface temperature of a different star is 4500 K. (c) Sketch, without a calculation, the approximate black-body spectrum of this star.", "marks": 2, "hint": "A cooler black body has a longer peak wavelength and a lower curve.", "answer": "Draw a lower peak shifted to the right, with a smaller total area under the curve.", "steps": ["Keep the same broad black-body curve shape.", "Move the peak right: lower T means larger λpeak.", "Lower the peak: the emitted intensity is smaller.", "For reference, λpeak ≈ 644 nm at 4500 K, versus about 483 nm at 6000 K. No calculation is required in your answer."], "check": ["Peak to the right.", "Lower peak and smaller area."], "promptImage": "assets/sc-prompt.png", "formulas": [{"name": "Wien’s displacement law", "equation": "λₚₑₐₖT = 2.90 × 10⁻³ m K", "symbols": "λ with subscript peak is the peak wavelength in metres; T is absolute temperature in kelvin. The rearranged versions are shown above.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mi>T</mi><mo>=</mo><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mspace width=\"0.2em\"/><mtext>m K</mtext></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><mi>T</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>2.90</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow><mrow><msub><mi>λ</mi><mrow><mtext>peak</mtext></mrow></msub></mrow></mfrac></mrow></math>"]}, {"name": "Total power per unit area", "equation": "P/A = σT⁴", "symbols": "A cooler black body emits less power per unit area. On the same intensity–wavelength axes, its curve has a smaller area and a lower peak. Use these relationships to guide the sketch; no calculation is needed.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mi>P</mi></mrow><mrow><mi>A</mi></mrow></mfrac><mo>=</mo><mi>σ</mi><msup><mi>T</mi><mn>4</mn></msup></mrow></math>"]}]}], "introImage": "assets/star-intro.png"}, {"id": "hail", "title": "A falling hailstone", "topic": "Density · Energy conservation", "image": "assets/q24.png", "intro": "During a hail storm spherical pieces of ice (hailstones) fall towards the surface of the Earth. The following data is given: Specific heat capacity of water: 4.19 kJ kg⁻¹ K⁻¹. Specific heat capacity of ice: 2.09 kJ kg⁻¹ K⁻¹. Specific latent heat of fusion of ice: 336 kJ kg⁻¹. Density of ice: 917 kg m⁻³. Initial temperature of ice: −21.5 °C. Radius of a hailstone: 3.20 cm.", "parts": [{"id": "ha", "label": "a", "q": "Calculate the mass of one hailstone to an appropriate number of significant figures.", "marks": 2, "hint": "Use the sphere volume V = 4πr³/3, then m = ρV.", "answer": "m = 0.126 kg (3 s.f.).", "steps": [{"text": "Start with density = mass ÷ volume.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>ρ</mi><mo>=</mo><mfrac><mrow><mi>m</mi></mrow><mrow><mi>V</mi></mrow></mfrac></mrow></math>"]}, {"text": "Multiply BOTH sides by V to make mass the subject.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>ρ</mi><mi>V</mi><mo>=</mo><mfrac><mrow><mi>m</mi></mrow><mrow><mi>V</mi></mrow></mfrac><mi>V</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mi>ρ</mi><mi>V</mi></mrow></math>"]}, {"text": "Write the sphere-volume equation and substitute it for V.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>V</mi><mo>=</mo><mfrac><mrow><mn>4</mn></mrow><mrow><mn>3</mn></mrow></mfrac><mi>π</mi><msup><mi>r</mi><mn>3</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mi>ρ</mi><mfrac><mrow><mn>4</mn></mrow><mrow><mn>3</mn></mrow></mfrac><mi>π</mi><msup><mi>r</mi><mn>3</mn></msup></mrow></math>"]}, {"text": "Convert the radius from centimetres to metres before cubing.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>r</mi><mo>=</mo><mfrac><mrow><mn>3.20</mn></mrow><mrow><mn>100</mn></mrow></mfrac><mo>=</mo><mn>0.0320</mn><mspace width=\"0.2em\"/><mtext>m</mtext></mrow></math>"]}, {"text": "Cube the radius.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msup><mi>r</mi><mn>3</mn></msup><mo>=</mo><msup><mn>0.0320</mn><mn>3</mn></msup><mo>=</mo><mn>3.2768</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>5</mn></mrow></msup><mspace width=\"0.2em\"/><msup><mtext>m</mtext><mn>3</mn></msup></mrow></math>"]}, {"text": "Calculate the volume.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>V</mi><mo>=</mo><mfrac><mrow><mn>4</mn></mrow><mrow><mn>3</mn></mrow></mfrac><mi>π</mi><mo>(</mo><mn>3.2768</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>5</mn></mrow></msup><mo>)</mo><mo>=</mo><mn>1.37258</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>4</mn></mrow></msup><mspace width=\"0.2em\"/><msup><mtext>m</mtext><mn>3</mn></msup></mrow></math>"]}, {"text": "Multiply density by volume.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mn>917</mn><mo>×</mo><mn>1.37258</mn><mo>×</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>4</mn></mrow></msup><mo>=</mo><mn>0.125866</mn><mspace width=\"0.2em\"/><mtext>kg</mtext></mrow></math>"]}, {"text": "Round to three significant figures.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mn>0.126</mn><mspace width=\"0.2em\"/><mtext>kg</mtext></mrow></math>"]}], "check": ["Convert radius to metres before cubing it.", "Use a sphere’s volume."], "promptImage": "assets/ha-prompt.png", "formulas": [{"name": "Density", "equation": "ρ = m/V  →  m = ρV", "symbols": "ρ = density (kg m⁻³); m = mass (kg); V = volume (m³).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>ρ</mi><mo>=</mo><mfrac><mrow><mi>m</mi></mrow><mrow><mi>V</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>ρ</mi><mi>V</mi><mo>=</mo><mfrac><mrow><mi>m</mi></mrow><mrow><mi>V</mi></mrow></mfrac><mi>V</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mi>ρ</mi><mi>V</mi></mrow></math>"]}, {"name": "Volume of a sphere", "equation": "V = (4/3)πr³", "symbols": "r = radius (m); V = volume (m³). Combine with density: m = ρ(4/3)πr³.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>V</mi><mo>=</mo><mfrac><mrow><mn>4</mn></mrow><mrow><mn>3</mn></mrow></mfrac><mi>π</mi><msup><mi>r</mi><mn>3</mn></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>m</mi><mo>=</mo><mi>ρ</mi><mfrac><mrow><mn>4</mn></mrow><mrow><mn>3</mn></mrow></mfrac><mi>π</mi><msup><mi>r</mi><mn>3</mn></msup></mrow></math>"]}]}, {"id": "hb", "label": "b", "q": "As the hailstone falls, 20% of the hailstone's initial gravitational potential energy is converted into the internal energy of the hailstone. After the hailstone falls through a vertical distance of H, its temperature increases by 1.80 °C. b. Find H.", "marks": 2, "hint": "Set 0.20mgH equal to mcΔT. The mass cancels.", "answer": "H ≈ 1.92 × 10³ m (using g = 9.81 m s⁻²).", "steps": [{"text": "Write the lost gravitational potential energy and the heating energy.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Δ</mi><msub><mi>E</mi><mi>p</mi></msub><mo>=</mo><mi>m</mi><mi>g</mi><mi>H</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"text": "Only 20% becomes heating energy. Write 20% as 0.20 and equate the energies.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>0.20</mn><mi>m</mi><mi>g</mi><mi>H</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"text": "Divide BOTH sides by m. The mass cancels.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mn>0.20</mn><mi>m</mi><mi>g</mi><mi>H</mi></mrow><mrow><mi>m</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mi>m</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>0.20</mn><mi>g</mi><mi>H</mi><mo>=</mo><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"text": "Divide BOTH sides by 0.20g.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mn>0.20</mn><mi>g</mi><mi>H</mi></mrow><mrow><mn>0.20</mn><mi>g</mi></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mn>0.20</mn><mi>g</mi></mrow></mfrac></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>H</mi><mo>=</mo><mfrac><mrow><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mn>0.20</mn><mi>g</mi></mrow></mfrac></mrow></math>"]}, {"text": "Use the heat capacity of ICE in joules and the temperature increase.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>c</mi><mo>=</mo><mn>2.09</mn><mo>×</mo><mn>1000</mn><mo>=</mo><mn>2090</mn><mspace width=\"0.2em\"/><msup><mtext>J kg</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup><msup><mtext>K</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>H</mi><mo>=</mo><mfrac><mrow><mn>2090</mn><mo>×</mo><mn>1.80</mn></mrow><mrow><mn>0.20</mn><mo>×</mo><mn>9.81</mn></mrow></mfrac></mrow></math>"]}, {"text": "Calculate the top and bottom separately, then divide.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>H</mi><mo>=</mo><mfrac><mrow><mn>3762</mn></mrow><mrow><mn>1.962</mn></mrow></mfrac><mo>=</mo><mn>1917.43</mn><mspace width=\"0.2em\"/><mtext>m</mtext></mrow></math>"]}, {"text": "A suitable rounded result is approximately 1.9 km. The 3 s.f. calculated value is shown; the stated 20% fraction may justify 2 s.f.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>H</mi><mo>≈</mo><mn>1.92</mn><mo>×</mo><msup><mn>10</mn><mn>3</mn></msup><mspace width=\"0.2em\"/><mtext>m</mtext></mrow></math>"]}], "check": ["Use 0.20 for 20%.", "Use the heat capacity of ice in J kg⁻¹ K⁻¹."], "promptImage": "assets/hb-prompt.png", "formulas": [{"name": "Gravitational potential energy lost", "equation": "ΔEₚ = mgH", "symbols": "m = hailstone mass (kg); g = 9.81 m s⁻²; H = vertical distance fallen (m).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Δ</mi><msub><mi>E</mi><mi>p</mi></msub><mo>=</mo><mi>m</mi><mi>g</mi><mi>H</mi></mrow></math>"]}, {"name": "Temperature change", "equation": "Q = mcΔT", "symbols": "Q = energy transferred (J); m = mass (kg); c = specific heat capacity (J kg⁻¹ K⁻¹); ΔT = temperature change (K).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"name": "Use the 20% heating fraction", "equation": "0.20mgH = mcΔT  →  H = cΔT/(0.20g)", "symbols": "Only 20% of the lost gravitational potential energy warms the hailstone. Cancel m from both sides and use the specific heat capacity of ice.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>0.20</mn><mi>m</mi><mi>g</mi><mi>H</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>H</mi><mo>=</mo><mfrac><mrow><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow><mrow><mn>0.20</mn><mi>g</mi></mrow></mfrac></mrow></math>"]}]}, {"id": "hc", "label": "c", "q": "When the hailstone reaches the surface of the Earth it falls into a puddle. The temperature of the hailstone at this moment is −10.0 °C. The mass of the water in the puddle is 8.30 kg and the initial temperature of the water in the puddle is 17.0 °C. c. Find T, the equilibrium temperature of the mixture. Assume that energy transfer only takes place between the hailstone and the water in the puddle.", "marks": 3, "hint": "The puddle cools. The ice first warms to 0 °C, melts, then the meltwater warms to T.", "answer": "T ≈ 15.5 °C. All the hailstone melts.", "steps": [{"text": "Use the unrounded hailstone mass from part (a). Name the water mass W and the hailstone mass m to keep the algebra short.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>W</mi><mo>=</mo><mn>8.30</mn><mspace width=\"0.2em\"/><mtext>kg</mtext><mspace width=\"1em\"/><mi>m</mi><mo>=</mo><mn>0.1258658404</mn><mspace width=\"0.2em\"/><mtext>kg</mtext></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>c</mi><mi>w</mi></msub><mo>=</mo><mn>4190</mn><mspace width=\"1em\"/><msub><mi>c</mi><mi>i</mi></msub><mo>=</mo><mn>2090</mn><mspace width=\"1em\"/><mi>L</mi><mo>=</mo><mn>336000</mn></mrow></math>"]}, {"text": "Check there is enough energy to melt ALL the ice. The puddle could release this much energy if it cooled to 0 °C.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mrow><mtext>available</mtext></mrow></msub><mo>=</mo><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mo>(</mo><mn>17</mn><mo>−</mo><mn>0</mn><mo>)</mo><mo>=</mo><mn>591209</mn><mspace width=\"0.2em\"/><mtext>J</mtext></mrow></math>"]}, {"text": "Warm the ice from −10 °C to 0 °C, then melt it. This needs much less energy than is available.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mrow><mtext>needed</mtext></mrow></msub><mo>=</mo><mi>m</mi><msub><mi>c</mi><mi>i</mi></msub><mo>×</mo><mn>10</mn><mo>+</mo><mi>m</mi><mi>L</mi></mrow></math>", "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mrow><mtext>needed</mtext></mrow></msub><mo>=</mo><mi>m</mi><mo>(</mo><mn>20900</mn><mo>+</mo><mn>336000</mn><mo>)</mo><mo>≈</mo><mn>44921.5</mn><mspace width=\"0.2em\"/><mtext>J</mtext></mrow></math>"]}, {"text": "All the ice melts. Equate energy lost by the puddle with the three energy gains by the ice.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mo>(</mo><mn>17</mn><mo>−</mo><mi>T</mi><mo>)</mo><mo>=</mo><mi>m</mi><msub><mi>c</mi><mi>i</mi></msub><mo>×</mo><mn>10</mn><mo>+</mo><mi>m</mi><mi>L</mi><mo>+</mo><mi>m</mi><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi></mrow></math>"]}, {"text": "Expand the bracket on the LEFT: multiply Wc_w by each term.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>17</mn><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mo>−</mo><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi><mo>=</mo><mn>10</mn><mi>m</mi><msub><mi>c</mi><mi>i</mi></msub><mo>+</mo><mi>m</mi><mi>L</mi><mo>+</mo><mi>m</mi><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi></mrow></math>"]}, {"text": "Add Wc_wT to BOTH sides.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>17</mn><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mo>=</mo><mn>10</mn><mi>m</mi><msub><mi>c</mi><mi>i</mi></msub><mo>+</mo><mi>m</mi><mi>L</mi><mo>+</mo><mi>m</mi><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi><mo>+</mo><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi></mrow></math>"]}, {"text": "Subtract the ice-warming and melting terms from BOTH sides.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>17</mn><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mo>−</mo><mn>10</mn><mi>m</mi><msub><mi>c</mi><mi>i</mi></msub><mo>−</mo><mi>m</mi><mi>L</mi><mo>=</mo><mi>m</mi><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi><mo>+</mo><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi></mrow></math>"]}, {"text": "Factor c_wT out of the two terms on the right.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>17</mn><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mo>−</mo><mn>10</mn><mi>m</mi><msub><mi>c</mi><mi>i</mi></msub><mo>−</mo><mi>m</mi><mi>L</mi><mo>=</mo><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi><mo>(</mo><mi>m</mi><mo>+</mo><mi>W</mi><mo>)</mo></mrow></math>"]}, {"text": "Divide BOTH sides by c_w(m + W).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mfrac><mrow><mn>17</mn><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mo>−</mo><mn>10</mn><mi>m</mi><msub><mi>c</mi><mi>i</mi></msub><mo>−</mo><mi>m</mi><mi>L</mi></mrow><mrow><msub><mi>c</mi><mi>w</mi></msub><mo>(</mo><mi>m</mi><mo>+</mo><mi>W</mi><mo>)</mo></mrow></mfrac><mo>=</mo><mfrac><mrow><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi><mo>(</mo><mi>m</mi><mo>+</mo><mi>W</mi><mo>)</mo></mrow><mrow><msub><mi>c</mi><mi>w</mi></msub><mo>(</mo><mi>m</mi><mo>+</mo><mi>W</mi><mo>)</mo></mrow></mfrac></mrow></math>"]}, {"text": "Cancel the common factors on the right. Write T first.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>17</mn><mi>W</mi><msub><mi>c</mi><mi>w</mi></msub><mo>−</mo><mi>m</mi><mo>(</mo><mn>10</mn><msub><mi>c</mi><mi>i</mi></msub><mo>+</mo><mi>L</mi><mo>)</mo></mrow><mrow><msub><mi>c</mi><mi>w</mi></msub><mo>(</mo><mi>W</mi><mo>+</mo><mi>m</mi><mo>)</mo></mrow></mfrac></mrow></math>"]}, {"text": "Insert the numerical values. Keep extra digits of the ice mass during calculation.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>17</mn><mo>×</mo><mn>8.30</mn><mo>×</mo><mn>4190</mn><mo>−</mo><mn>0.1258658404</mn><mo>(</mo><mn>10</mn><mo>×</mo><mn>2090</mn><mo>+</mo><mn>336000</mn><mo>)</mo></mrow><mrow><mn>4190</mn><mo>(</mo><mn>8.30</mn><mo>+</mo><mn>0.1258658404</mn><mo>)</mo></mrow></mfrac></mrow></math>"]}, {"text": "Work out the top and bottom separately.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>591209</mn><mo>−</mo><mn>44921.51844</mn></mrow><mrow><mn>35304.37787</mn></mrow></mfrac></mrow></math>"]}, {"text": "Subtract the numerator, then divide.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mfrac><mrow><mn>546287.48156</mn></mrow><mrow><mn>35304.37787</mn></mrow></mfrac><mo>=</mo><mn>15.47365</mn><mspace width=\"0.2em\"/><msup><mrow></mrow><mrow><mo>°</mo></mrow></msup><mtext>C</mtext></mrow></math>"]}, {"text": "Round to three significant figures. It is below the initial puddle temperature of 17.0 °C, as expected.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>T</mi><mo>=</mo><mn>15.5</mn><mspace width=\"0.2em\"/><msup><mrow></mrow><mrow><mo>°</mo></mrow></msup><mtext>C</mtext></mrow></math>"]}], "check": ["Use −10.0 °C for this part, as specified.", "Include warming the ice, melting it and warming the meltwater.", "The final temperature must be below 17.0 °C."], "promptImage": "assets/hc-prompt.png", "formulas": [{"name": "Conservation of energy", "equation": "Energy lost = energy gained", "symbols": "For these mixture calculations, add the energy for each stage: warming ice, melting ice and warming the melted water. Assume no energy exchange with the surroundings.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>Q</mi><mrow><mtext>lost</mtext></mrow></msub><mo>=</mo><msub><mi>Q</mi><mrow><mtext>gained</mtext></mrow></msub></mrow></math>"]}, {"name": "Temperature change", "equation": "Q = mcΔT", "symbols": "Q = energy transferred (J); m = mass (kg); c = specific heat capacity (J kg⁻¹ K⁻¹); ΔT = temperature change (K).", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>c</mi><mi>Δ</mi><mi>T</mi></mrow></math>"]}, {"name": "Change of state", "equation": "Q = mL", "symbols": "Q = energy transferred (J); m = mass (kg); L = specific latent heat (J kg⁻¹). Temperature stays constant during the change of state.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>Q</mi><mo>=</mo><mi>m</mi><mi>L</mi></mrow></math>"]}, {"name": "Write the complete energy balance", "equation": "m_water c_water (T_water − T) = m_ice c_ice (0 − T_ice) + m_ice L + m_ice c_water (T − 0)", "symbols": "m_w = puddle-water mass; m_i = hailstone mass; c_w and c_i = specific heat capacities of water and ice; T_w = initial puddle temperature; T_i = initial ice temperature; T = final temperature. The ice warms to 0 °C, melts, then the meltwater warms to T.", "math": ["<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><msub><mi>m</mi><mi>w</mi></msub><msub><mi>c</mi><mi>w</mi></msub><mo>(</mo><msub><mi>T</mi><mi>w</mi></msub><mo>−</mo><mi>T</mi><mo>)</mo><mo>=</mo><msub><mi>m</mi><mi>i</mi></msub><msub><mi>c</mi><mi>i</mi></msub><mo>(</mo><mn>0</mn><mo>−</mo><msub><mi>T</mi><mi>i</mi></msub><mo>)</mo><mo>+</mo><msub><mi>m</mi><mi>i</mi></msub><mi>L</mi><mo>+</mo><msub><mi>m</mi><mi>i</mi></msub><msub><mi>c</mi><mi>w</mi></msub><mi>T</mi></mrow></math>"]}]}], "introImage": "assets/hail-intro.png"}];